using UnityEngine;
using UnityEditor;

public class SpawnFences {
    public static void Main() {
        string assetPath = "Assets/Model/House/3D Voxel Park Pack/Park Furnishings/Park_Fence_Edge.obj";
        GameObject fencePrefab = AssetDatabase.LoadAssetAtPath<GameObject>(assetPath);
        if (fencePrefab == null) {
            Debug.LogError("Failed to load fence model at " + assetPath);
            return;
        }

        GameObject decors = GameObject.Find("City_Decors");
        GameObject parentGo = GameObject.Find("City_Decors/Fences");
        if (parentGo == null) {
            parentGo = new GameObject("Fences");
            if (decors != null) parentGo.transform.SetParent(decors.transform);
        }

        float fenceWidth = 1.6f;
        float startX = -40f;
        float endX = 40f;
        float startZ = 30f;
        float endZ = 90f;

        int count = 0;

        // 1. South Edge: Z = 30, X from startX to endX
        for (float x = startX; x <= endX; x += fenceWidth) {
            // Leave a small gap in the middle for access (e.g. X between -3 and 3)
            if (x > -3.5f && x < 3.5f) continue;

            GameObject fence = (GameObject)PrefabUtility.InstantiatePrefab(fencePrefab);
            if (fence == null) fence = GameObject.Instantiate(fencePrefab);

            fence.name = "Fence_South_" + count;
            fence.transform.position = new Vector3(x, -0.5f, 30f);
            fence.transform.rotation = Quaternion.Euler(0, 0, 0);
            fence.transform.SetParent(parentGo.transform);
            Undo.RegisterCreatedObjectUndo(fence, "Spawn Fence");
            count++;
        }

        // 2. North Edge: Z = 90, X from startX to endX
        for (float x = startX; x <= endX; x += fenceWidth) {
            if (x > -3.5f && x < 3.5f) continue;

            GameObject fence = (GameObject)PrefabUtility.InstantiatePrefab(fencePrefab);
            if (fence == null) fence = GameObject.Instantiate(fencePrefab);

            fence.name = "Fence_North_" + count;
            fence.transform.position = new Vector3(x, -0.5f, 90f);
            fence.transform.rotation = Quaternion.Euler(0, 180f, 0);
            fence.transform.SetParent(parentGo.transform);
            Undo.RegisterCreatedObjectUndo(fence, "Spawn Fence");
            count++;
        }

        // 3. West Edge: X = -40, Z from startZ to endZ
        for (float z = startZ; z <= endZ; z += fenceWidth) {
            if (z > 56.5f && z < 63.5f) continue; // Gap in the middle of West path

            GameObject fence = (GameObject)PrefabUtility.InstantiatePrefab(fencePrefab);
            if (fence == null) fence = GameObject.Instantiate(fencePrefab);

            fence.name = "Fence_West_" + count;
            fence.transform.position = new Vector3(-40f, -0.5f, z);
            fence.transform.rotation = Quaternion.Euler(0, 90f, 0);
            fence.transform.SetParent(parentGo.transform);
            Undo.RegisterCreatedObjectUndo(fence, "Spawn Fence");
            count++;
        }

        // 4. East Edge: X = 40, Z from startZ to endZ
        for (float z = startZ; z <= endZ; z += fenceWidth) {
            if (z > 56.5f && z < 63.5f) continue; // Gap in the middle of East path

            GameObject fence = (GameObject)PrefabUtility.InstantiatePrefab(fencePrefab);
            if (fence == null) fence = GameObject.Instantiate(fencePrefab);

            fence.name = "Fence_East_" + count;
            fence.transform.position = new Vector3(40f, -0.5f, z);
            fence.transform.rotation = Quaternion.Euler(0, -90f, 0);
            fence.transform.SetParent(parentGo.transform);
            Undo.RegisterCreatedObjectUndo(fence, "Spawn Fence");
            count++;
        }

        Debug.Log("Spawned " + count + " fence pieces surrounding the lake.");

        // Mark scene dirty and save
        UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());
        UnityEditor.SceneManagement.EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());
        Debug.Log("Scene saved successfully with fences.");
    }
}
